// FPC Code Validator - Stack-Simulation und Syntax-Pruefung
const code = $input.first().json.query || $input.first().json.chatInput || '';

const VALID_COMMANDS = ['GET','GETNOT','DUP','NOT','AND','OR','XOR','MOV','CMOV','SET','CSET','CINC','CDEC','CMP','GT','LE'];
const VALID_SUBJECTS = ['I','O','M','T','C'];

const RESOURCE_LIMITS = {
  'I': 64, 'O': 64, 'M': 1024, 'T': 128, 'C': 128
};

const STACK_EFFECTS = {
  'GET': { pop: 0, push: 1 },
  'GETNOT': { pop: 0, push: 1 },
  'DUP': { pop: 0, push: 1, needsMin: 1 },
  'NOT': { pop: 1, push: 1 },
  'AND': { pop: 2, push: 1 },
  'OR': { pop: 2, push: 1 },
  'XOR': { pop: 2, push: 1 },
  'MOV': { pop: 1, push: 0 },
  'CMOV': { pop: 1, push: 0 },
  'SET': { pop: 0, push: 0 },
  'CSET': { pop: 1, push: 0 },
  'CINC': { pop: 0, push: 0 },
  'CDEC': { pop: 0, push: 0 },
  'CMP': { pop: 0, push: 1 },
  'GT': { pop: 0, push: 1 },
  'LE': { pop: 0, push: 1 }
};

const lines = code.split('\n').map(l => l.trim()).filter(l => l.length > 0);
const errors = [];
const stackTrace = [];
let stackDepth = 0;
let lineNumber = 0;

for (const line of lines) {
  lineNumber++;

  // Skip comments
  if (line.startsWith('#')) {
    stackTrace.push({ line: lineNumber, instruction: line, stackBefore: stackDepth, stackAfter: stackDepth, comment: true });
    continue;
  }

  // Parse instruction
  const parts = line.split(/\s+/);
  const cmd = parts[0].toUpperCase();

  // Check valid command
  if (!VALID_COMMANDS.includes(cmd)) {
    errors.push({ line: lineNumber, error: `Unbekannter Befehl: ${cmd}`, code: line });
    continue;
  }

  const effect = STACK_EFFECTS[cmd];
  const stackBefore = stackDepth;

  // Check minimum stack requirements
  const minRequired = effect.needsMin || effect.pop;
  if (stackDepth < minRequired) {
    errors.push({ 
      line: lineNumber, 
      error: `Stack-Unterlauf: ${cmd} benoetigt ${minRequired} Wert(e), Stack hat ${stackDepth}`,
      code: line
    });
  }

  // Check subject and address for commands that need them
  if (['GET', 'GETNOT', 'MOV', 'CMOV', 'SET', 'CSET', 'CINC', 'CDEC', 'CMP', 'GT', 'LE'].includes(cmd)) {
    if (cmd === 'GET' && parts.length === 2 && (parts[1] === '0' || parts[1] === '1')) {
      // GET 0 or GET 1 - constants, valid
    } else if (parts.length < 3) {
      // Allow shorthand like I0 -> I 0
      if (parts.length === 2 && /^[IOTMC]\d+$/.test(parts[1])) {
        // Shorthand notation OK
        const subject = parts[1][0].toUpperCase();
        const address = parseInt(parts[1].substring(1));
        if (!VALID_SUBJECTS.includes(subject)) {
          errors.push({ line: lineNumber, error: `Ungueltiger Operand: ${parts[1]}`, code: line });
        } else if (address < 0 || address >= RESOURCE_LIMITS[subject]) {
          errors.push({ line: lineNumber, error: `Adresse ${address} ausserhalb des Bereichs fuer ${subject} (0-${RESOURCE_LIMITS[subject]-1})`, code: line });
        }
      } else if (parts.length >= 2) {
        // Could be valid with fewer params for some commands
      } else {
        errors.push({ line: lineNumber, error: `${cmd} benoetigt Operanden`, code: line });
      }
    } else {
      const subject = parts[1].toUpperCase();
      const address = parseInt(parts[2]);
      if (!VALID_SUBJECTS.includes(subject) && !['0','1'].includes(parts[1])) {
        errors.push({ line: lineNumber, error: `Ungueltiger Operand-Typ: ${subject}`, code: line });
      } else if (!isNaN(address)) {
        if (VALID_SUBJECTS.includes(subject) && (address < 0 || address >= RESOURCE_LIMITS[subject])) {
          errors.push({ line: lineNumber, error: `Adresse ${address} ausserhalb des Bereichs fuer ${subject} (0-${RESOURCE_LIMITS[subject]-1})`, code: line });
        }
      }
    }
  }

  // Apply stack effect
  stackDepth = Math.max(0, stackDepth - effect.pop + effect.push);

  stackTrace.push({
    line: lineNumber,
    instruction: line,
    stackBefore: stackBefore,
    stackAfter: stackDepth,
    comment: false
  });
}

// Check final stack depth
if (stackDepth !== 0) {
  errors.push({ 
    line: lineNumber, 
    error: `Stack nicht leer am Programmende: Tiefe = ${stackDepth} (erwartet: 0)`,
    code: 'END'
  });
}

const valid = errors.length === 0;

let result = `## Validierungsergebnis: ${valid ? 'GUELTIG' : 'FEHLERHAFT'}\n\n`;

if (!valid) {
  result += '### Fehler:\n';
  for (const err of errors) {
    result += `- Zeile ${err.line}: ${err.error} \`${err.code}\`\n`;
  }
  result += '\n';
}

result += '### Stack-Trace:\n';
for (const trace of stackTrace) {
  if (!trace.comment) {
    result += `Zeile ${trace.line}: [${trace.stackBefore}] -> \`${trace.instruction}\` -> [${trace.stackAfter}]\n`;
  }
}

return result;
